    - src
  exclude: []
documentation:
  scan:
    - '*.md'
<?php

declare(strict_types=1);

namespace Guard\Config\Project;

use Guard\Diagnostic\PolicyException;
use Guard\Structure\Markdown\HeadingParser;
use JsonException;
use Symfony\Component\Yaml\Yaml;

/**
 * Creates a versioned guard policy for the tools present in the target project.
 */
final class Initializer
{
    /**
     * @param ?list<string> $imports null selects presets from the project; a list imports only those names
     * @throws PolicyException when guard.yaml exists, cannot be created, or names an unknown preset
     * @throws JsonException when composer.json or composer.lock is malformed
     */
    public function write(string $path, ?array $imports = null): void
    {
        if (file_exists($path) || is_link($path)) {
            throw new PolicyException('Cannot create ' . $path . ': it already exists. Review the existing policy instead of overwriting it.');
        }
        $data = $this->configuration(dirname($path), $imports);
        $source = "# Project policy. Required rules fail; recommendations warn.\n" . Yaml::dump($data, 12, 2, Yaml::DUMP_EMPTY_ARRAY_AS_SEQUENCE);
        $handle = @fopen($path, 'x');
        if ($handle === false) {
            throw new PolicyException('Cannot create ' . $path . '. It must not exist and its directory must be writable.');
        }
        try {
            if (fwrite($handle, $source) !== strlen($source)) {
                throw new PolicyException('Could not finish writing ' . $path . '. Check disk space.');
            }
        } finally {
            fclose($handle);
        }
    }
    /**
     * Builds a project policy that imports shipped presets and keeps project-specific sections inline.
     *
     * @param ?list<string> $imports null selects presets from the project; a list imports only those names
     * @return array<string, mixed>
     * @throws JsonException when composer.json or composer.lock is malformed
     * @throws PolicyException when an import name is unknown or a preset cannot be read
     */
    public function configuration(string $root, ?array $imports = null): array
    {
        $names = (new PresetSelector())->select($root, $imports);
        $document = ['version' => 1];
        $paths = (new PresetCatalog())->imports($root, $names);
        if ($paths !== []) {
            $document['imports'] = $paths;
        }
        if (in_array('metrics', $names, true)) {
            $document['metrics'] = ['source' => (new ToolDetector())->sources($root), 'exclude' => []];
        }
        $readme = $this->readme($root);
        if ($readme !== null) {
            $document['documentation'] = $readme;
        }
        $document = (new PresetOverrides())->apply($root, $names, $document);
        if (in_array('test-dependencies', $names, true)) {
            $document['test_dependencies'] = (new TestDependencySetup())->settings($root);
        }

        return (new LegacyMigration())->migrate($root, $document, in_array('disable-doc', $names, true));
    }

    /**
     * Returns the current README headings when the project has a README.
     *
     * @return ?array<string, mixed>
     */
    public function readme(string $root): ?array
    {
        if (!is_file($root . '/README.md')) {
            return null;
        }
        $source = file_get_contents($root . '/README.md');
        $headings = [];
        foreach ((new HeadingParser())->parse($source === false ? '' : $source) as $heading) {
            $headings[] = $heading->notation();
        }

        return ['files' => ['README.md' => ['headings' => $headings]], 'scan' => ['README.md']];
    }

    /**
     * Returns the standard metric limits shipped in rules/metrics.yaml.
     *
     * @return array<string, array<string, int>>
     * @throws PolicyException when metrics.yaml does not define integer limits
     */
    public function limits(): array
    {
        return (new PresetCatalog())->limits();
    }
    /**
     * @param list<string> $sources
     * @return array<string, mixed>
     */
    public function structure(array $sources, bool $hasUnitTests = false): array
    {
        $directories = [['path' => '**', 'deny_dirs' => ['scripts', 'Scripts']]];
        foreach ($sources as $source) {
            $directories[] = ['path' => $source, 'allow' => [], 'max_dirs' => 20];
            $directories[] = ['path' => $source . '/**', 'forbid_empty' => true, 'allow' => ['*.php'],
                'deny' => ['*Helper.php', '*Helpers.php', '*Manager.php', '*Util.php', '*Utils.php', '*Service.php', '*Evidence.php', '*Evidences.php', '*Outcome.php', '*Outcomes.php', '*Probe.php', '*Probes.php'],
                'file_case' => 'pascal', 'dir_case' => 'pascal', 'max_files' => 15, 'max_dirs' => 20];
        }
        if ($hasUnitTests) {
            $directories[] = ['path' => 'tests/Unit', 'allow' => []];
            $directories[] = ['path' => 'tests/Unit/**', 'forbid_empty' => true, 'allow' => ['*Test.php'],
                'file_case' => 'pascal', 'dir_case' => 'pascal', 'max_files' => 15, 'max_dirs' => 20];
        }
        $directories[] = ['path' => 'skills/*', 'require' => ['SKILL.md'], 'forbid_empty' => true];
        return ['paths' => ['.'], 'exclude' => ['.git', '.idea', '.claude', '.agents', '.codex', '.cursor', '.gemini', '.entire', '.entrie', '.phpunit.cache', 'build', 'projects', 'vendor'], 'directories' => $directories];
    }
}
<?php

declare(strict_types=1);

namespace Guard\Config;

use Guard\Config\Reader\MetricPolicyReader;
use Guard\Policy\Diagnostic\FieldMessage;
use Guard\Policy\Diagnostic\RuleDescription;
use Guard\Policy\Diagnostic\RuleMessages;
use JsonException;

/**
 * Lists the effective policy after imports, overrides, defaults and inheritance.
 */
final class RuleCatalog
{
    /**
     * Diagnostic identifiers emitted by each document constraint.
     */
    private const DOCUMENT_RULES = [
        'headings' => ['unexpected_heading', 'missing_heading', 'renamed_heading', 'changed_heading_level', 'moved_heading'],
        'outlines' => ['unexpected_outline_heading', 'missing_outline_heading'],
        'badges' => ['missing_badges', 'unexpected_badge', 'missing_badge'],
        'content' => ['unexpected_content'],
    ];

    /**
     * @return list<RuleDescription>
     * @throws JsonException
     */
    public function load(string $path): array
    {
        /**
         * Validate the entire configuration even when a query selects only one rule.
         */
        $configuration = (new ConfigurationLoader())->load($path);
        $data = (new ImportResolver())->resolve($path);
        $rules = $this->fields($data['configuration'] ?? []);
        if (array_key_exists('test_dependencies', $data)) {
            $dependencyRules = (new Reader\TestDependencyConfigReader())->read($data['test_dependencies']);
            $rules[] = new RuleDescription('test-dependencies', implode(', ', array_keys($dependencyRules->files())), 'required', true, 'For each existing bench/, fuzz/, spec/, or tests/ directory, require its autoload-dev PSR-4 mapping and an independent Deptrac layer that can depend only on src/ production layers. Run guard fix to configure the boundaries.', ['directories' => $dependencyRules->directories()]);
        }
        if (array_key_exists('metrics', $data)) {
            $rules = array_merge($rules, $this->metrics($data['metrics'], dirname($path)));
        }
        if (array_key_exists('structure', $data)) {
            $rules = array_merge($rules, $this->structure($data['structure']));
        }
        if (array_key_exists('documentation', $data)) {
            $rules = array_merge($rules, $this->documentation($data['documentation']));
        }
        foreach ($rules as $rule) {
            if ($configuration->scope !== null) {
                $rule->details['collect'] = ['include' => $configuration->scope->include, 'exclude' => $configuration->scope->exclude];
                if (str_starts_with($rule->id, 'metrics.')) {
                    $rule->target = '**/*.php within collect';
                    unset($rule->details['source'], $rule->details['exclude']);
                }
            }
        }
        foreach ((new Reader\ExtensionConfigReader())->read($data['extensions'] ?? []) as $class => $options) {
            $rules[] = new RuleDescription(
                'extension:' . $class,
                $class,
                'extension',
                false,
                'This configured policy or structurer defines its own behavior. Consult its documentation for diagnostics, remediation and repair capabilities.',
                $options
            );
        }
        return $rules;
    }

    /**
     * @return list<RuleDescription>
     * @throws JsonException
     */
    public function fields(mixed $value): array
    {
        $rules = [];
        foreach ((new RuleReader())->read($value) as $rule) {
            $details = ['format' => $rule->format, 'select' => $rule->select, 'assert' => $rule->assertions];
            if ($rule->repairable) {
                $details['repair'] = $rule->repair;
            }
            $rules[] = new RuleDescription(
                $rule->id,
                $rule->file,
                $rule->level,
                $rule->repairable,
                (new FieldMessage())->render($rule),
                $details
            );
        }
        return $rules;
    }

    /**
     * @return list<RuleDescription>
     */
    public function metrics(mixed $value, string $root): array
    {
        $config = (new MetricPolicyReader())->read($value, $root);
        $assignments = [];
        foreach ($config->apply->rules as $assignment) {
            $assignments[] = ['name' => $assignment->name, 'paths' => $assignment->paths, 'profile' => $assignment->policy];
        }
        $used = array_merge([$config->apply->defaultPolicy], array_column($assignments, 'profile'));
        $rules = [];
        foreach ($config->policies as $profile => $policy) {
            if (!in_array($profile, $used, true)) {
                continue;
            }
            foreach ($policy->limits->values() as $metric => $limit) {
                if ($limit === null) {
                    continue;
                }
                $id = str_ends_with($metric, '.cyclomatic_complexity') ? 'metrics.cyclomatic_complexity' : 'metrics.' . str_replace('.', '_', $metric);
                $rules[] = new RuleDescription(
                    $id,
                    implode(', ', $config->scan->roots),
                    'required',
                    false,
                    (new RuleMessages())->forRule($id),
                    ['profile' => $profile, 'metric' => $metric, 'max' => $limit, 'source' => $config->scan->roots, 'exclude' => $config->scan->exclude,
                        'default' => $config->apply->defaultPolicy, 'assignments' => $assignments]
                );
            }
        }
        return $rules;
    }

    /**
     * @return list<RuleDescription>
     */
    public function structure(mixed $value): array
    {
        $data = (new Schema())->mapping($value, ['paths', 'exclude', 'directories'], 'structure');
        $rules = [];
        $ids = ['allow' => 'disallowed_file', 'deny' => 'denied_file', 'allow_dirs' => 'disallowed_dir', 'deny_dirs' => 'denied_dir',
            'require' => 'missing_required_file', 'forbid_empty' => 'empty_directory'];
        $entries = $data['directories'] ?? [];
        if (!is_array($entries)) {
            return [];
        }
        foreach ($entries as $entry) {
            if (!is_array($entry) || !is_string($entry['path'] ?? null)) {
                continue;
            }
            foreach ($entry as $key => $constraint) {
                if (!is_string($key) || $key === 'path' || $constraint === null || $constraint === false) {
                    continue;
                }
                $id = 'structure.' . ($ids[$key] ?? $key);
                $rules[] = new RuleDescription(
                    $id,
                    $entry['path'],
                    'required',
                    false,
                    (new RuleMessages())->forRule($id),
                    [$key => $constraint, 'paths' => $data['paths'] ?? ['.'], 'exclude' => $data['exclude'] ?? []]
                );
            }
        }
        return $rules;
    }

    /**
     * @return list<RuleDescription>
     */
    public function documentation(mixed $value): array
    {
        $data = (new Schema())->mapping($value, ['files', 'scan', 'exclude'], 'documentation');
        $rules = [];
        $files = $data['files'] ?? [];
        if (!is_array($files)) {
            return [];
        }
        foreach ($files as $path => $settings) {
            if (!is_string($path) || !is_array($settings)) {
                continue;
            }
            $rules[] = new RuleDescription(
                'documentation.missing_document',
                $path,
                'required',
                false,
                (new RuleMessages())->forRule('documentation.missing_document')
            );
            foreach ($settings as $key => $constraint) {
                if (!is_string($key) || $key === 'max_level' || $constraint === null) {
                    continue;
                }
                $ids = self::DOCUMENT_RULES[$key] ?? [];
                foreach ($ids as $suffix) {
                    $id = 'documentation.' . $suffix;
                    $rules[] = new RuleDescription(
                        $id,
                        $path,
                        'required',
                        false,
                        (new RuleMessages())->forRule($id),
                        [$key => $constraint, 'max_level' => $settings['max_level'] ?? 6]
                    );
                }
            }
        }
        if (($data['scan'] ?? []) !== []) {
            $rules[] = new RuleDescription(
                'documentation.undeclared_document',
                implode(', ', (new Schema())->strings($data['scan'], 'documentation.scan')),
                'required',
                false,
                (new RuleMessages())->forRule('documentation.undeclared_document'),
                ['exclude' => $data['exclude'] ?? []]
            );
        }
        return $rules;
    }
}
